using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.ENC.TiposPregunta{    [SwaggerSchema("Modelo de lectura de un TiposPregunta")]    [GraphQLDescription("Objeto que representa un TiposPregunta existente.")]    public class clReadTiposPregunta    {        [SwaggerSchema("Identificador único del TiposPregunta")]        [GraphQLDescription("Identificador único del TiposPregunta")]        public int? TipoPreguntaID { get; set; }        [SwaggerSchema("TipoPregunta")]        [GraphQLDescription("TipoPregunta")]        public string? TipoPregunta { get; set; } = default!;        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un TiposPregunta")]    [GraphQLDescription("Input para crear un TiposPregunta.")]    public class clCreateTiposPregunta    {        [GraphQLNonNullType] [SwaggerSchema("TipoPregunta")]        [GraphQLDescription("TipoPregunta")]        public string TipoPregunta { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un TiposPregunta")]    [GraphQLDescription("Input para actualizar parcialmente un TiposPregunta.")]    public class clUpdateTiposPregunta    {        [SwaggerSchema("Identificador único del TiposPregunta")]        [GraphQLDescription("Identificador único del TiposPregunta")]        public int? TipoPreguntaID { get; set; }        [SwaggerSchema("TipoPregunta")]        [GraphQLDescription("TipoPregunta")]        public string? TipoPregunta { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}